def join(*paths):
    if not paths:
        return ""

    result_parts = []
    for p in paths:
        if p:  # Only process non-empty paths
            if p.startswith('/'):
                # Absolute path found, discard previous segments
                result_parts = [p]
            else:
                result_parts.append(p)

    if not result_parts:
        return ""

    joined = "/".join(result_parts)
    return normpath(joined)

